SCRIPT='''
let current=1;const TOTAL=16;
function show(n){current=Math.max(1,Math.min(TOTAL,n));document.querySelectorAll('.slide').forEach((s,i)=>s.classList.toggle('on',i+1===current));document.getElementById('count').textContent=current+' / '+TOTAL;document.getElementById('bar').style.width=(current/TOTAL*100)+'%';document.getElementById('prev').disabled=current===1;document.getElementById('next').disabled=current===TOTAL;if(location.hash!=='#s'+current)history.replaceState(null,'','#s'+current);window.scrollTo(0,0)}
function fromHash(){show(Number(location.hash.match(/s(\\d+)/)?.[1]||1))}
prev.onclick=()=>show(current-1);next.onclick=()=>show(current+1);
addEventListener('hashchange',fromHash);addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,button,[contenteditable="true"]'))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}});
document.getElementById('mapBtn').onclick=()=>{const x=document.getElementById('map');x.hidden=!x.hidden};document.querySelectorAll('#map a').forEach(a=>a.onclick=()=>document.getElementById('map').hidden=true);
document.getElementById('fs').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.()};
const definitions=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(QUESTION_DATA),c=>c.charCodeAt(0))));
document.querySelectorAll('[data-question]').forEach(box=>{const index=Number(box.dataset.question),[question,options,answer]=definitions[index];const label=document.createElement('label');label.textContent='Autocomprobación formativa · '+question;const select=document.createElement('select');select.id='answer-'+index;label.htmlFor=select.id;const first=new Option('Elige una opción…','');select.append(first);for(const [key,text] of options)select.append(new Option(text,key));const button=document.createElement('button');button.type='button';button.textContent='Comprobar';const feedback=document.createElement('div');feedback.className='feedback';feedback.setAttribute('aria-live','polite');button.onclick=()=>{const option=options.find(x=>x[0]===select.value);feedback.textContent=option?((select.value===answer?'✓ Correcto. ':'Revisa. ')+option[2]+' · Práctica libre, sin nota ni registro oficial.'):'Elige una opción.'};box.append(label,select,button,feedback)});
imageFile.onchange=()=>{const f=imageFile.files?.[0],box=document.getElementById('imagePreview');if(!f)return;box.replaceChildren();const img=new Image(),url=URL.createObjectURL(f);img.alt='Imagen real seleccionada localmente para inspeccionar dimensiones y conservar contexto.';img.onload=()=>{const text=document.createElement('p');text.textContent=f.name+' · '+f.size+' bytes · '+img.naturalWidth+'×'+img.naturalHeight+' px. El tipo real se confirma con el decoder del proyecto.';box.append(text,img);URL.revokeObjectURL(url)};img.onerror=()=>{box.textContent='No se pudo decodificar. Recupera el original real; no se crea un sustituto.';URL.revokeObjectURL(url)};img.src=url};
catalogFile.onchange=async()=>{const f=catalogFile.files?.[0],box=document.getElementById('catalogPreview');if(!f)return;box.replaceChildren();try{if(f.size>10*1024*1024)throw Error('Archivo mayor del límite de vista local');const text=await f.text(),rows=text.trim().split(/\\r?\\n/).filter(Boolean).map(x=>JSON.parse(x));if(!rows.length)throw Error('Catálogo vacío');const p=document.createElement('p');p.textContent=rows.length+' filas de archivo local; esta vista no verifica integridad ni registra una entrega.';const t=document.createElement('table'),head=document.createElement('tr');for(const name of ['article_id','profile','derived_width','derived_height']){const th=document.createElement('th');th.textContent=name;head.append(th)}t.append(head);for(const row of rows.slice(0,5)){const tr=document.createElement('tr');for(const name of ['article_id','profile','derived_width','derived_height']){const td=document.createElement('td');td.textContent=String(row[name]??'—');tr.append(td)}t.append(tr)}box.append(p,t)}catch(e){box.textContent='No se abrió el catálogo: '+e.message}};
// Las visitas solo registran acceso; nunca verifican la ejecución del laboratorio.
if(window.BIGDATA_LMS?.auth?.()?.user){
  window.LMS?.track('presentation_opened',{session_number:10,activity_code:'bd-s10-presentation'}).catch(()=>{});
  document.querySelectorAll('a[href$="s10_proyecto_VSCode.zip"]').forEach(a=>a.addEventListener('click',()=>{
    window.LMS?.track('resource_opened',{session_number:10,activity_code:'bd-s10-project'}).catch(()=>{});
  }));
}
fromHash();
'''

def build():
    sections='\n'.join(f'<section class="slide" id="s{i}" data-slide="{i}"><div class="slide-content"><div class="k">S10 · {html.escape(k)}</div><h1>{h}</h1><div class="body">{b}</div></div></section>' for i,(k,h,b) in enumerate(SLIDES,1))
    links=''.join(f'<a href="#s{i}">{i} · {html.escape(k)}</a>' for i,(k,h,b) in enumerate(SLIDES,1))
    encoded=base64.b64encode(json.dumps(QUESTIONS,ensure_ascii=False).encode()).decode()
    return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>S10 · ETL de imágenes reales en VS Code</title><style>'+STYLE+'</style></head><body><div id="bar" class="bar"></div><header class="top"><span>VS Code · E → T → L</span><a href="'+PROJECT+'" target="_blank" rel="noopener">Proyecto</a><a class="optional" href="../assets/tutoriales/s10-laboratorio-guiado.html">Tutorial</a><button id="mapBtn" type="button">Mapa</button><button id="fs" type="button" aria-label="Pantalla completa">⛶</button></header><main class="stage">'+sections+'</main><aside id="map" class="drawer" hidden aria-label="Mapa de la sesión">'+links+'</aside><nav class="nav" aria-label="Diapositivas"><button id="prev" type="button" aria-label="Anterior">←</button><span id="count"></span><button id="next" type="button" aria-label="Siguiente">→</button></nav><script src="../lms/assets/bigdata-lms.js"></script><script src="../lms/assets/lms-kit.js" data-session="10"></script><script>const QUESTION_DATA="'+encoded+'";'+SCRIPT+'</script></body></html>\n'

if __name__=='__main__':OUT.write_text(build(),encoding='utf-8');print(OUT)
